// include benchmark-specific definitions (for trisolv)
#include "trisolv.hpp"

using num_t = DATA_TYPE;

namespace {

// dimension proto-structures
constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

// layouts for individual arrays
struct tuning {
	// L: i x j  (row i, column j)
	DEFINE_PROTO_STRUCT(l_layout, j_vec ^ i_vec);
	// x: i
	DEFINE_PROTO_STRUCT(x_layout, i_vec);
	// b: i
	DEFINE_PROTO_STRUCT(b_layout, i_vec);
} tuning;

// Array initialization.
// L: n x n lower triangular
// x: length n
// b: length n
void init_array(auto L, auto x, auto b) {
	using namespace noarr;

	// problem size from structure
	auto n = L | get_length<'i'>();

	// initialize x and b: for i in [0, n)
	traverser(x, b).for_each([=](auto state) {
		auto i = get_index<'i'>(state);

		x[state] = (num_t)-999;
		b[state] = (num_t)i;
	});

	// initialize L: lower triangular part only
	// Original code iterated all j and used `if (j <= i)`.
	// Here we restrict the traverser to j ∈ [0, i] directly, removing the branch
	// and avoiding useless iterations over j > i.
	traverser(L).template for_dims<'i'>([=](auto inner_i) {
		auto state_i = inner_i.state();
		auto i = get_index<'i'>(state_i);

		// restrict j to [0, i] (length i+1, so j = 0..i)
		auto row_trav = inner_i.order(noarr::slice<'j'>(0, i + 1));

		row_trav.for_each([=](auto state_ij) {
			auto j = get_index<'j'>(state_ij);

			// for all j in [0, i]:
			//   L[i][j] = (i + n - j + 1) * 2 / n;
			// keep arithmetic identical to original: cast (i + n - j + 1) first
			L[state_ij] = (num_t)(i + n - j + 1) * 2 / n;
		});
	});
}

// Main computational kernel:
// for i = 0..n-1:
//   x[i] = b[i];
//   for j = 0..i-1:
//     x[i] -= L[i][j] * x[j];
//   x[i] = x[i] / L[i][i];
//
// Optimizations vs original version:
// - Keep the outer traversal over i identical (sequential dependency in i).
// - For each fixed i, restrict the inner traversal to j ∈ [0, i-1] using
//   noarr::slice instead of iterating all j and checking `if (j < i)`.
//   This halves the number of inner iterations on average and removes a branch.
// - Accumulate into a local register variable `xi` instead of repeatedly
//   reading/writing x[i] from memory; x[i] is written only once per i.
//   Semantics are preserved: the recurrence for x[i] is unchanged.
[[gnu::flatten, gnu::noinline]]
void kernel_trisolv(auto L, auto x, auto b) {
	using namespace noarr;

#pragma scop
	// traverse in the 'i' dimension outermost, as in the original code
	traverser(L).template for_dims<'i'>([=](auto inner_i) {
		// state with current i fixed
		auto state_i = inner_i.state();
		auto i = get_index<'i'>(state_i);

		// start from the RHS: x[i] = b[i]
		num_t xi = b[state_i];

		// Inner loop over j: original code did
		//   for all j: if (j < i) x[i] -= L[i][j] * x[j];
		// We now traverse only j ∈ [0, i-1], so the condition is implicit.
		if (i > 0) { // avoid creating a slice with negative length
			auto row_trav = inner_i.order(noarr::slice<'j'>(0, i));

			row_trav.for_each([&](auto state_ij) {
				auto j = get_index<'j'>(state_ij);

				// L[i][j] is indexed by (i, j) in 'state_ij'
				// x[j] is indexed by 'i' = j
				xi -= L[state_ij] * x[noarr::idx<'i'>(j)];
			});
		}

		// divide by diagonal element: x[i] = x[i] / L[i][i];
		auto diag_state = noarr::idx<'i', 'j'>(i, i);
		xi /= L[diag_state];

		// write the final value back once
		x[state_i] = xi;
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;

	// set lengths for dimensions
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n);

	// allocate data (bags own the memory)
	auto L = noarr::bag(noarr::scalar<num_t>() ^ tuning.l_layout ^ set_lengths);
	auto x = noarr::bag(noarr::scalar<num_t>() ^ tuning.x_layout ^ set_lengths);
	auto b = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);

	// initialize arrays
	init_array(L.get_ref(), x.get_ref(), b.get_ref());

	// start timer
	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_trisolv(L.get_ref(), x.get_ref(), b.get_ref());

	// stop timer
	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print results (prevents dead-code elimination of computation)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, x.get_ref());
	}

	// print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
